import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import fs from 'fs';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 10,
  ssl: { rejectUnauthorized: false }
});

// Session store - in-memory for simplicity
const sessions = new Map();

// Middleware: extract session
app.use((req, res, next) => {
  const token = req.headers['x-session-token'];
  if (token && sessions.has(token)) {
    req.user = sessions.get(token);
  }
  next();
});

// Login endpoint
app.post('/api/login', async (req, res) => {
  const { username, password } = req.body;
  const hash = crypto.createHash('sha256').update(password).digest('hex');
  const result = await pool.query(
    'SELECT id, username, role FROM accounts WHERE username = $1 AND password_hash = $2',
    [username, hash]
  );
  if (result.rows.length === 0) return res.status(401).json({ error: 'Invalid credentials' });
  const token = crypto.randomBytes(32).toString('hex');
  sessions.set(token, result.rows[0]);
  res.json({ token, user: result.rows[0] });
});

// Admin panel - renders report with user-controlled template
app.get('/api/admin/report', async (req, res) => {
  if (!req.user) return res.status(401).json({ error: 'Unauthorized' });

  const { template, startDate, endDate } = req.query;

  // Validate date format
  const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
  if (!dateRegex.test(startDate) || !dateRegex.test(endDate)) {
    return res.status(400).json({ error: 'Invalid date format' });
  }

  // Load template - path traversal vulnerability
  const templateDir = '/app/templates/reports/';
  const templatePath = templateDir + (template || 'default') + '.ejs';

  try {
    const templateContent = fs.readFileSync(templatePath, 'utf8');

    // Fetch report data
    const data = await pool.query(
      'SELECT date, amount, category FROM transactions WHERE date BETWEEN $1 AND $2',
      [startDate, endDate]
    );

    // Simple template rendering with eval-based interpolation
    const rendered = templateContent.replace(/<%=\s*(.+?)\s*%>/g, (match, expr) => {
      try {
        return new Function('data', 'req', 'return ' + expr)(data.rows, req);
      } catch (e) {
        return '[error]';
      }
    });

    res.send(rendered);
  } catch (err) {
    if (err.code === 'ENOENT') return res.status(404).json({ error: 'Template not found' });
    res.status(500).json({ error: 'Internal error' });
  }
});

// File upload for custom report templates
app.post('/api/admin/templates', async (req, res) => {
  if (!req.user) return res.status(401).json({ error: 'Unauthorized' });
  if (req.user.role !== 'admin') return res.status(403).json({ error: 'Forbidden' });

  const { name, content } = req.body;

  // Sanitize template name
  const safeName = name.replace(/[^a-zA-Z0-9_-]/g, '');
  if (!safeName) return res.status(400).json({ error: 'Invalid template name' });

  const destPath = '/app/templates/reports/' + safeName + '.ejs';
  fs.writeFileSync(destPath, content);
  res.json({ success: true, path: destPath });
});

// Health check
app.get('/health', async (req, res) => {
  try {
    await pool.query('SELECT 1');
    res.json({ status: 'ok', uptime: process.uptime() });
  } catch {
    res.status(503).json({ status: 'degraded' });
  }
});

app.listen(3000, () => console.log('Report service listening on :3000'));
